    ['slug' => 'jasy', 'name' => 'Jasy', 'gender' => 'f', 'origin' => 'guaraní', 'meaning' => 'Luna; también mes, según el contexto guaraní.', 'tags' => ['corto', 'guarani'], 'note' => 'La y guaraní es una vocal distinta de la i y de la y castellana. Consultá la pronunciación con una persona hablante.', 'native_form' => 'jasy', 'review' => ['status' => 'qualified', 'sources' => [['title' => 'Diccionario Guaraní-Castellano, Sugar Labs: jasy', 'url' => 'https://github.com/sugarlabs/diccionario-guarani-castellano-activity/blob/f0001d16948e07227880cebc9be208473c652990/lang/guarani/dic.txt#L756', 'checked' => '2026-10-17', 'scope' => 'Sentido léxico; no acredita frecuencia, género ni uso como nombre personal.']], 'note' => 'Sentido léxico contrastado con una fuente educativa; uso como nombre propio y ortografía pendientes de revisión especializada.'], 'context' => 'Jasy tiene dos sentidos que conviene distinguir: luna y mes. El diccionario citado registra ambos. Si lo elegís por la luna, esa es la asociación que podés compartir con tu familia. Conservá la y final y no des por hecho que una adaptación escrita con i o con otra letra tiene la misma pronunciación. Para escucharlo, recurrí a una persona hablante de guaraní.'],
    ['slug' => 'yvoty', 'name' => 'Yvoty', 'gender' => 'f', 'origin' => 'guaraní', 'meaning' => 'Flor, en guaraní.', 'tags' => ['guarani'], 'note' => 'Conservá la y de la escritura guaraní; reemplazarla por i no es una equivalencia ortográfica automática.', 'native_form' => 'yvoty', 'review' => ['status' => 'qualified', 'sources' => [['title' => 'Diccionario Guaraní-Castellano, Sugar Labs: yvoty', 'url' => 'https://github.com/sugarlabs/diccionario-guarani-castellano-activity/blob/f0001d16948e07227880cebc9be208473c652990/lang/guarani/dic.txt#L3614', 'checked' => '2026-10-17', 'scope' => 'Sentido léxico; no acredita frecuencia, género ni uso como nombre personal.']], 'note' => 'Sentido léxico contrastado con una fuente educativa; uso como nombre propio y ortografía pendientes de revisión especializada.'], 'context' => 'La referencia léxica de Yvoty es la flor. Si te atraen los nombres inspirados en la naturaleza, podés compararlo con Flor o Violeta, que también están en el catálogo. Poty merece su propia ficha: el diccionario registra flor y florecer, y no lo tratamos como un simple diminutivo de Yvoty. Antes de decidir, practicá la escritura completa, incluida la y.', 'compare' => ['flor', 'violeta', 'poty']],
